result = 0
for i in range(len(operator) - 1):
    op1, op2 = operator[i], operand[i]
    if op1 == '+':
        result += op2
    elif op1 == '-':
        result -= op2
    elif op1 == '*':
        result *= op2
    elif op1 == '/':
        result //= op2
    elif op1 == '**':
        result **= op2
return result
